#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/ghcr.io-dragonflydb-dragonfly-v2.1.0-arm64-oci ] || "$F" ghcr.io/dragonflydb/dragonfly sha256:3a31efa21abea5f648c044a2071f1e2183f0ac64d4c7e6b542ce3fa1004a4aa5 ghcr.io/dragonflydb/dragonfly:v2.1.0 images/ghcr.io-dragonflydb-dragonfly-v2.1.0-arm64-oci
[ "$A" = arm64 ] || [ -f images/ghcr.io-dragonflydb-dragonfly-v2.1.0-amd64.docker.tar ] || "$F" ghcr.io/dragonflydb/dragonfly sha256:1936953db764986adfdcc8ffd347e50665299ad0c1e761c8fe2b888330821022 ghcr.io/dragonflydb/dragonfly:v2.1.0 images/ghcr.io-dragonflydb-dragonfly-v2.1.0-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/ghcr.io-dragonflydb-dragonfly-v2.1.0-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/ghcr.io-dragonflydb-dragonfly-v2.1.0-arm64-oci
